const llmOutput = $input.all();
//console.log(llmOutput[0].json.text)

let parsed = [];

llmOutput.forEach(e => {
    const item = typeof e.json.text === 'string' ? JSON.parse(e.json.text) : e.json.text;
    parsed.push(item);
});

console.log(parsed)
return parsed
return [
    {
        json: {
            clarity: parsed.clarity,
            structure: parsed.structure,
            precision: parsed.precision,
            tone: parsed.tone,
            grammar: parsed.grammar,
            information: parsed.information,
            writing_quality_score: parsed.writing_quality_score,
            helpfulness_rate: parsed.helpfulness_rate,
            correlation: parsed.correlation,
            comment: parsed.comment
        }
    }
];

const reviews = $input.all().map(item => item.json); // n8n Input Items

console.log(reviews)

let sumScores = {
    clarity: 0,
    structure: 0,
    precision: 0,
    tone: 0,
    grammar: 0,
    information: 0,
    writing_quality_score: 0,
    helpfulness_rate: 0
};

let count = reviews.length;
let correlationYes = 0;

reviews.forEach(r => {
    sumScores.clarity += Number(r.clarity);
    sumScores.structure += Number(r.structure);
    sumScores.precision += Number(r.precision);
    sumScores.tone += Number(r.tone);
    sumScores.grammar += Number(r.grammar);
    sumScores.information += Number(r.information);
    sumScores.writing_quality_score += Number(r.writing_quality_score);
    sumScores.helpfulness_rate += Number(r.helpfulness_rate);

    if(r.correlation === "yes") correlationYes++;
});

const averages = {};
for (const key in sumScores) {
    averages[key] = sumScores[key] / count;
}

const correlationRate = correlationYes / count;

return [
    {
        json: {
            count,
            averages,
            correlationRate,
        }
    }
];

// Beispiel: Alle Review-Daten in "reviews" Array
const reviews = $input.all().map(item => item.json); // n8n Input Items

// Aggregation vorbereiten
let sumScores = {
    clarity: 0,
    structure: 0,
    precision: 0,
    tone: 0,
    grammar: 0,
    information: 0,
    writing_quality_score: 0,
    helpfulness_rate: 0
};

let count = reviews.length;
let correlationYes = 0;

// Summe berechnen
reviews.forEach(r => {
    sumScores.clarity += Number(r.output.clarity);
    sumScores.structure += Number(r.output.structure);
    sumScores.precision += Number(r.output.precision);
    sumScores.tone += Number(r.output.tone);
    sumScores.grammar += Number(r.output.grammar);
    sumScores.information += Number(r.output.information);
    sumScores.writing_quality_score += Number(r.output.writing_quality_score);
    sumScores.helpfulness_rate += Number(r.output.helpfulness_rate);

    if(r.output.correlation === "yes") correlationYes++;
});

// Durchschnitt berechnen
const averages = {};
for (const key in sumScores) {
    averages[key] = sumScores[key] / count;
}

// Anteil der Reviews mit positiver Korrelation
const correlationRate = correlationYes / count;

return [
    {
        json: {
            count,
            averages,
            correlationRate,
        }
    }
];

